using System.Windows.Input;
using VisualRelay.Domain;

namespace VisualRelay.App.ViewModels.RunLogRows;

/// <summary>
/// Display-layer row abstraction for the Run Log <c>ListBox</c>.
/// Each visible row is either a <see cref="SingleEventRow"/> wrapping
/// a single <see cref="RelayEvent"/>, or a <see cref="HeartbeatGroupRow"/>
/// collapsing a contiguous run of <c>watchdog_heartbeat</c> events.
/// </summary>
public interface IRunLogRow
{
    string DisplayLine { get; }
    string DetailLine { get; }
    bool IsAttention { get; }
    bool IsGroup { get; }
    int Count { get; }
    RelayEvent Event { get; }
    IReadOnlyList<RelayEvent> Members { get; }
    bool IsExpanded { get; set; }
    ICommand ToggleExpandCommand { get; }
}

using System.Windows.Input;
using VisualRelay.Domain;

namespace VisualRelay.App.ViewModels.RunLogRows;

/// <summary>
/// Wraps a single <see cref="RelayEvent"/> as a Run Log row.
/// Delegates <see cref="DisplayLine"/>, <see cref="DetailLine"/>,
/// and <see cref="IsAttention"/> straight through.
/// </summary>
public sealed class SingleEventRow : IRunLogRow
{
    private static readonly ICommand NoOpCommand = new RelayCommand(() => { });

    public SingleEventRow(RelayEvent relayEvent)
    {
        Event = relayEvent;
    }

    public string DisplayLine => Event.DisplayLine;
    public string DetailLine => Event.DetailLine;
    public bool IsAttention => Event.IsAttention;
    public bool IsGroup => false;
    public int Count => 1;
    public RelayEvent Event { get; }
    public IReadOnlyList<RelayEvent> Members { get; private set; } = Array.Empty<RelayEvent>();
    public bool IsExpanded
    {
        get => false;
        set { /* no-op */ }
    }
    public ICommand ToggleExpandCommand => NoOpCommand;

    /// <summary>
    /// Initialise <see cref="Members"/> from the wrapped event.
    /// Called after construction so the same member array is available.
    /// </summary>
    internal void InitMembers()
    {
        Members = new[] { Event };
    }
}

/// <summary>
/// Minimal <see cref="ICommand"/> whose <c>Execute</c> is a no-op.
/// Used by <see cref="SingleEventRow"/> for the required
/// <see cref="IRunLogRow.ToggleExpandCommand"/>.
/// </summary>
internal sealed class RelayCommand : ICommand
{
    private readonly Action _execute;
    public RelayCommand(Action execute) => _execute = execute;
    public event EventHandler? CanExecuteChanged;
    public bool CanExecute(object? parameter) => true;
    public void Execute(object? parameter) => _execute();
}

