namespace VisualRelay.App.ViewModels.RunLogRows;

/// <summary>
/// A collapsed group of consecutive <c>watchdog_heartbeat</c> events
/// with identical <c>(StageNumber, Tier)</c>. Displays the shared
/// <see cref="DisplayLine"/> plus a count (e.g. "×30") and shows the
/// <b>newest</b> member's <see cref="DetailLine"/>.
/// </summary>
public partial class HeartbeatGroupRow : ObservableObject, IRunLogRow
{
    private readonly List<RelayEvent> _members;

    private HeartbeatGroupRow()
    {
        _members = [];
        Members = new ReadOnlyCollection<RelayEvent>(_members);
        ToggleExpandCommand = new RelayCommand(ToggleExpand);
    }

    /// <summary>
    /// Factory: returns a <see cref="SingleEventRow"/> when <paramref name="events"/>
    /// contains exactly one element, otherwise a <see cref="HeartbeatGroupRow"/>.
    /// Events must be newest-first and all share the same <c>DisplayLine</c>.
    /// </summary>
    public static IRunLogRow Create(params RelayEvent[] events)
    {
        if (events.Length == 1)
            return new SingleEventRow(events[0]);

        var row = new HeartbeatGroupRow();
        row._members.AddRange(events);
        row.Count = events.Length;
        return row;
    }

    /// <summary>
    /// Creates a group seeded with a list of events (newest-first).
    /// All events must share the same <c>DisplayLine</c>.
    /// </summary>
    public static HeartbeatGroupRow FromList(List<RelayEvent> events)
    {
        var row = new HeartbeatGroupRow();
        row._members.AddRange(events);
        row.Count = events.Count;
        return row;
    }

    public string DisplayLine => _members[0].DisplayLine;
    public string DetailLine => _members[0].DetailLine;
    public bool IsAttention => false;
    public bool IsGroup => true;
    public RelayEvent Event => _members[0];

    [ObservableProperty]
    private int _count;

    [ObservableProperty]
    private bool _isExpanded;

    public IReadOnlyList<RelayEvent> Members { get; }
    public ICommand ToggleExpandCommand { get; }

    /// <summary>
    /// Live-merge: prepend <paramref name="relayEvent"/> (the newest arrival)
    /// and increment the count. Does not collapse an expanded group.
    /// </summary>
    public void InsertNewest(RelayEvent relayEvent)
    {
        _members.Insert(0, relayEvent);
        Count = _members.Count;
        OnPropertyChanged(nameof(DisplayLine));
        OnPropertyChanged(nameof(DetailLine));
        OnPropertyChanged(nameof(Event));
    }

    private void ToggleExpand()
    {
        IsExpanded = !IsExpanded;
    }
}

using System.Collections.ObjectModel;
using VisualRelay.Domain;

namespace VisualRelay.App.ViewModels.RunLogRows;

/// <summary>
/// Shared grouping logic consumed by both population paths
/// (incremental insert and <see cref="MainWindowViewModel.ApplyLogFilter"/> rebuild)
/// so live drains, stage-filter flips, and finished-task history group identically.
/// </summary>
public static class RunLogGrouper
{
    /// <summary>
    /// Convert a flat, newest-first sequence of <see cref="RelayEvent"/> into
    /// display rows. Consecutive <c>watchdog_heartbeat</c> events with identical
    /// <c>DisplayLine</c> collapse into a single <see cref="HeartbeatGroupRow"/>
    /// (or a <see cref="SingleEventRow"/> when the run length is 1).
    /// Every non-heartbeat event becomes a plain <see cref="SingleEventRow"/>.
    /// </summary>
    public static List<IRunLogRow> GroupEvents(IEnumerable<RelayEvent> events)
    {
        var rows = new List<IRunLogRow>();
        List<RelayEvent>? pendingHeartbeats = null;

        foreach (var evt in events)
        {
            if (evt.EventName == "watchdog_heartbeat")
            {
                if (pendingHeartbeats is { Count: > 0 } &&
                    pendingHeartbeats[^1].DisplayLine != evt.DisplayLine)
                {
                    FlushPendingHeartbeats(rows, ref pendingHeartbeats);
                }

                pendingHeartbeats ??= [];
                pendingHeartbeats.Add(evt);
            }
            else
            {
                FlushPendingHeartbeats(rows, ref pendingHeartbeats);
                rows.Add(new SingleEventRow(evt));
            }
        }

        FlushPendingHeartbeats(rows, ref pendingHeartbeats);
        return rows;
    }

    /// <summary>
    /// Attempt to merge <paramref name="relayEvent"/> into the newest row
    /// (index 0) of <paramref name="rows"/>. Returns <c>true</c> when the
    /// event was merged (either into an existing <see cref="HeartbeatGroupRow"/>
    /// or by promoting a lone-heartbeat <see cref="SingleEventRow"/> to a group).
    /// </summary>
    public static bool MergeNewest(
        ObservableCollection<IRunLogRow> rows,
        RelayEvent relayEvent)
    {
        if (relayEvent.EventName != "watchdog_heartbeat")
            return false;

        if (rows.Count == 0)
            return false;

        var newest = rows[0];

        // Case 1: newest row is a heartbeat group — check match and merge.
        if (newest is HeartbeatGroupRow group)
        {
            if (group.DisplayLine != relayEvent.DisplayLine)
                return false;

            group.InsertNewest(relayEvent);
            return true;
        }

        // Case 2: newest row is a single heartbeat — promote to group.
        if (newest is SingleEventRow single &&
            single.Event.EventName == "watchdog_heartbeat" &&
            single.DisplayLine == relayEvent.DisplayLine)
        {
            var promoted = HeartbeatGroupRow.FromList(
                new List<RelayEvent> { relayEvent, single.Event });
            promoted.IsExpanded = single.IsExpanded;
            rows[0] = promoted;
            return true;
        }

        return false;
    }

    private static void FlushPendingHeartbeats(
        List<IRunLogRow> rows,
        ref List<RelayEvent>? pending)
    {
        if (pending is not { Count: > 0 })
            return;

        rows.Add(HeartbeatGroupRow.Create(pending.ToArray()));
        pending = null;
    }
}

